package com.projeto.carrinhoPraiagp02;
import static org.junit.jupiter.api.Assertions.*;import java.math.BigDecimal;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;import com.projeto.carrinhoPraiagp02.models.*;import com.projeto.carrinhoPraiagp02.repository.*;import com.projeto.carrinhoPraiagp02.service.*;
@SpringBootTest(properties="app.payment.simulation.approved=false") @Transactional class DeclinedCheckoutIntegrationTest {
 @Autowired CheckoutService checkout;@Autowired CarrinhoService carts;@Autowired ComandaRepo comandas;@Autowired ProdutoRepo products;@Autowired PedidoRepo orders;@Autowired PagamentoRepo payments;@Autowired VendasRepo sales;
 @Test void rejectedSimulationCreatesNoOrderOrSaleAndNoStockChange(){Comanda c=comandas.save(new Comanda("DECL-1","Client"));Produto p=new Produto();p.setNome("Product");p.setDescricao("");p.setPreco(new BigDecimal("5"));p.setQuantidadeEstoque(3);p.setEstoqueMinimo(1);p.setCategoria("Test");p.setDisponibilidade(true);products.save(p);Carrinho cart=carts.criar(c.getNumero());carts.adicionar(cart.getId(),cart.getAccessToken(),p.getId(),1);assertThrows(com.projeto.carrinhoPraiagp02.exception.PaymentDeclinedException.class,()->checkout.checkout(cart.getId(),cart.getAccessToken(),"PIX","tester"));assertEquals(0,orders.count());assertEquals(1,payments.count());assertEquals("CANCELADO",payments.findAll().get(0).getStatus());assertEquals(0,sales.count());assertEquals(3,products.findById(p.getId()).orElseThrow().getQuantidadeEstoque());}
}
